S_LIST = [672, 696]
ITERS = 60
GROUPS = 8
K_SAMPLES = 3
TIME_BUDGET = 3600
INIT_NAME = 'bc_model.npz'
TAU = 1.0
LR = 1e-5
CLIP = 0.2
KL_BETA = 0.02
MARGIN_SCALE = 5000.0
WIN_W = 0.5
SIGMA_MIN = 0.2
PPO_EPOCHS = 2
MB = 64
EVAL_EVERY = 5
WARM_SEEDS = list(range(810000001, 810000033))
VAL_SEEDS = list(range(820000001, 820000005))
TEST_SEEDS = list(range(840100001, 840100017))
WARM_EPOCHS = 8
random.seed(20260923)


# ===================================== RL driver: group rollouts from forked v12 states =====================================
# v12 plays both seats up to a start step S. There the rollout process forks: one child continues with v12 (baseline),
# one with the greedy policy, K with the sampled policy. Children share the exact state and world, so their margins
# differ only through our seat's decisions (and v12's reaction to them). Sampled children train the policy with
# group-relative advantages and a PPO-clipped, KL-to-reference update.
import pickle, copy
import numpy as np
sys.path.insert(0, '/kaggle/working')
import bcm, legal, lean
UA, NQ, MARKET_HEADS, MARKET_SIZES = bcm.UA, bcm.NQ, bcm.MARKET_HEADS, bcm.MARKET_SIZES
PASS_I = UA.index('PASS')


class _Fork(BaseException):
    pass


_WCACHE = {}


def load_w(path):
    if path not in _WCACHE:
        z = np.load(path)
        _WCACHE.clear(); _WCACHE[path] = {k: z[k].astype(np.float32) for k in z.files}
    return _WCACHE[path]


from policy import policy_act

def rollout_group(job):
    seed, P, S_list, K, tau, wpath = job
    W = load_w(wpath)
    A = lean.load('/kaggle/working/v12.py'); B = lean.load('/kaggle/working/v12.py')
    st = dict(kind=None, children=[], errors=0, last_error=None)
    S_set = sorted(S_list)
    t0 = time.time()

    def ours(obs, cfg=None):
        t = int(obs['step'])
        if st['kind'] is None and t in S_set:
            for i in range(K + 2):
                path = '/tmp/rl_%d_%d_%d.pkl' % (os.getpid(), t, i)
                pid = os.fork()
                if pid == 0:
                    st['kind'] = 'v12' if i == 0 else ('greedy' if i == 1 else 'sample')
                    st['rng'] = np.random.default_rng([seed & 0x7fffffff, t, i])
                    st['rec'] = [] if i >= 2 else None
                    st['S'] = t; st['path'] = path; st['t0'] = time.time()
                    break
                st['children'].append((pid, path, t, i))
            if st['kind'] is None and t == S_set[-1]:
                raise _Fork()
        if st['kind'] in (None, 'v12'):
            return A(obs, cfg)
        try:
            return policy_act(obs, W, tau, st['rng'], st['kind'] == 'greedy', st['rec'])
        except Exception as e:
            st['errors'] += 1; st['last_error'] = repr(e)[:200]
            farm = obs['farms'][int(obs['player'])]
            return {'farmer': ['PASS'], 'hands': [['PASS'] for _ in farm['hands']], 'market': []}
    ag = [None, None]; ag[P] = ours; ag[1 - P] = B
    r = None
    try:
        r = lean.play(None, None, seed, agent_objs=ag)
    except _Fork:
        pass
    except Exception as e:
        if st['kind'] is None:
            return dict(seed=seed, P=P, children=[], error=repr(e)[:300])
    if st['kind'] is not None:
        try:
            out = dict(kind=st['kind'], S=st['S'], r=(r or {}).get('r'), errors=st['errors'], last_error=st['last_error'],
                       rec=st['rec'], wall=time.time() - st['t0'])
            with open(st['path'] + '.tmp', 'wb') as fh:
                pickle.dump(out, fh, protocol=4)
            os.replace(st['path'] + '.tmp', st['path'])
        finally:
            os._exit(0)
    res = []
    for pid, path, t, i in st['children']:
        os.waitpid(pid, 0)
        try:
            with open(path, 'rb') as fh:
                res.append(pickle.load(fh))
            os.remove(path)
        except Exception as e:
            res.append(dict(kind='lost', S=t, r=None, errors=1, last_error=repr(e)[:200], rec=None))
    return dict(seed=seed, P=P, children=res, wall=time.time() - t0)


def group_stats(g):
    """Per start step: margins of the v12 continuation, the greedy policy and the sampled policy."""
    P = g['P']; out = {}
    for c in g['children']:
        if c['r'] is None or c['r'][0] is None or c['r'][1] is None:
            continue
        m = c['r'][P] - c['r'][1 - P]
        e = out.setdefault(c['S'], dict(v12=None, greedy=None, sample=[], recs=[], errors=0))
        e['errors'] += c['errors'] or 0
        if c['kind'] == 'sample':
            e['sample'].append(m); e['recs'].append(c['rec'])
        elif c['kind'] in ('v12', 'greedy'):
            e[c['kind']] = m
    return out


def teacher_game(seed):
    """Collect incumbent decisions only on its own late-game trajectory."""
    rows = []
    A = lean.load('/kaggle/working/v12.py')
    B = lean.load('/kaggle/working/v12.py')

    def wrapped(p, inner):
        def act(obs, cfg):
            action = inner(obs, cfg)
            if obs['step'] >= min(S_LIST):
                grid, glob, uvec = bcm.encode(obs, p, bcm.features)
                grid, glob, uv = bcm.quantize(grid, glob, [u[1] for u in uvec])
                commands = [action.get('farmer', ['PASS'])] + list(action.get('hands') or [])
                labels = [bcm.unit_label(commands[k] if k < len(commands) else ['PASS']) for k in range(len(uvec))]
                acts = np.asarray([a for a, q in labels], np.int16)
                qs = np.asarray([q for a, q in labels], np.int8)
                qb = np.asarray([NQ if UA[a].startswith('PICKUP_') else 0 for a in acts], np.int8)
                mk = bcm.market_labels(action.get('market') or [])
                rows.append(dict(grid=grid, glob=glob, upos=np.asarray([u[0] for u in uvec], np.int8),
                                 uv=np.asarray(uv), mask=np.ones((len(uvec), len(UA)), bool),
                                 act=acts, qb=qb, q=qs, mk=np.asarray([mk[h] for h in MARKET_HEADS], np.int16), adv=0.0))
            return action
        return act

    result = lean.play(None, None, seed, agent_objs=[wrapped(0, A), wrapped(1, B)])
    assert result['err'] == [None, None], result['err']
    return rows


def summarize_eval(groups):
    """One row per independent seed, seat, and continuation start."""
    rows = []
    for g in groups:
        assert not g.get('error'), g.get('error')
        assert not any(c.get('errors') or c['r'] is None or None in c['r'] for c in g['children']), 'evaluation failure'
        for S, e in group_stats(g).items():
            assert e['v12'] is not None and e['greedy'] is not None
            rows.append(dict(seed=g['seed'], seat=g['P'], start=S,
                             baseline_margin=e['v12'], policy_margin=e['greedy'],
                             delta=e['greedy'] - e['v12']))
    return rows


def main():
    import multiprocessing as mp
    from concurrent.futures import ProcessPoolExecutor
    t_start = time.time()
    ncpu = os.cpu_count() or 4
    nw = max(1, ncpu // max(2, (K_SAMPLES + 2) // 2))
    ex = ProcessPoolExecutor(nw, mp_context=mp.get_context('spawn'))
    print('cpus', ncpu, 'rollout workers', nw, flush=True)
    import torch
    import torch.nn as nn
    import torch.nn.functional as F
    torch.set_num_threads(1)
    dev = 'cpu'  # bounded CPU pilot; workers never inherit a CUDA context
    init = sorted(glob.glob('/kaggle/input/**/%s' % INIT_NAME, recursive=True))[0]
    W0 = dict(np.load(init))
    H = W0['c0.weight'].shape[0]; NG = W0['g.weight'].shape[1]; NA = len(UA); C = W0['c0.weight'].shape[1]
    print('init', init, 'hidden', H, 'globals', NG, 'device', dev, flush=True)

    class Net(nn.Module):
        def __init__(self):
            super().__init__()
            self.c0 = nn.Conv2d(C, H, 3, padding=1); self.c1 = nn.Conv2d(H, H, 3, padding=1)
            self.c2 = nn.Conv2d(H, H, 3, padding=1); self.c3 = nn.Conv2d(H, H, 3, padding=1)
            self.g = nn.Linear(NG, H)
            self.u1 = nn.Linear(5 * H + H + H + bcm.N_UNIT, 256); self.ua = nn.Linear(256, NA); self.uq = nn.Linear(256, NQ)
            self.m1 = nn.Linear(2 * H, 256)
            self.mh = nn.ModuleDict({('mh_' + n): nn.Linear(256, s) for n, s in zip(MARKET_HEADS, MARKET_SIZES)})

    net = Net().to(dev)
    net.load_state_dict({('mh.' + k if k.startswith('mh_') else k): torch.as_tensor(v) for k, v in W0.items()})
    ref = copy.deepcopy(net).eval()
    for p_ in ref.parameters():
        p_.requires_grad_(False)
    opt = torch.optim.Adam(net.parameters(), lr=LR)

    def export(path):
        W = {k.replace('mh.mh_', 'mh_'): v.detach().cpu().numpy().astype(np.float32) for k, v in net.state_dict().items()}
        np.savez(path, **W)

    def batch(steps):
        grid = torch.as_tensor(np.stack([s['grid'] for s in steps]).astype(np.float32), device=dev)
        gl = torch.as_tensor(np.stack([s['glob'] for s in steps]), device=dev)
        li = np.concatenate([np.full(len(s['act']), j) for j, s in enumerate(steps)])
        up = np.concatenate([s['upos'] for s in steps]).astype(np.int64)
        T = lambda a, dt=torch.long: torch.as_tensor(a, device=dev, dtype=dt)
        return dict(grid=grid, glob=gl, li=T(li), x=T(up[:, 0]), y=T(up[:, 1]),
                    uv=T(np.concatenate([s['uv'] for s in steps]), torch.float32), mask=T(np.concatenate([s['mask'] for s in steps]), torch.bool),
                    act=T(np.concatenate([s['act'] for s in steps]).astype(np.int64)), qb=T(np.concatenate([s['qb'] for s in steps]).astype(np.int64)),
                    q=T(np.concatenate([s['q'] for s in steps]).astype(np.int64)), mk=T(np.stack([s['mk'] for s in steps]).astype(np.int64)),
                    adv=T(np.asarray([s['adv'] for s in steps], np.float32), torch.float32))

    def dists(model, b):
        h = b['grid']
        for c in (model.c0, model.c1, model.c2, model.c3):
            h = F.relu(c(h))
        gv = F.relu(model.g(b['glob'])); pooled = h.mean((2, 3))
        hp = F.pad(h, (1, 1, 1, 1)); li, x, y = b['li'], b['x'], b['y']
        feats = [hp[li, :, y + 1, x + 1], hp[li, :, y, x + 1], hp[li, :, y + 2, x + 1], hp[li, :, y + 1, x + 2], hp[li, :, y + 1, x]]
        z = F.relu(model.u1(torch.cat(feats + [pooled[li], gv[li], b['uv']], 1)))
        lpa = F.log_softmax((model.ua(z) / TAU).masked_fill(~b['mask'], -1e9), 1)
        ar = torch.arange(NQ, device=dev)[None]
        lpq = F.log_softmax((model.uq(z) / TAU).masked_fill(ar >= b['qb'].clamp(min=1)[:, None], -1e9), 1)
        m = F.relu(model.m1(torch.cat([pooled, gv], 1)))
        lpm = [F.log_softmax(model.mh['mh_' + n](m) / TAU, 1) for n in MARKET_HEADS]
        return lpa, lpq, lpm

    def taken(b, lpa, lpq, lpm):
        la = lpa.gather(1, b['act'][:, None])[:, 0]
        lq = lpq.gather(1, b['q'][:, None])[:, 0]
        lm = torch.stack([lpm[j].gather(1, b['mk'][:, j:j + 1])[:, 0] for j in range(len(MARKET_HEADS))], 1)
        return la, lq, lm

    def kl(lp, lr):
        return (lp.exp() * (lp - lr)).sum(-1)

    import shutil
    history = []
    evaluations = []
    best_score = None
    best_label = None
    selection_labels = []

    def joint(b, la, lq, lm):
        out = lm.sum(1)
        return out.index_add(0, b['li'], la + lq * (b['qb'] > 0).float())

    def assert_export_parity(model, b):
        """NumPy behavior versus Torch learner, all conditional log probabilities."""
        W = {k.replace('mh.mh_', 'mh_'): v.detach().cpu().numpy() for k, v in model.state_dict().items()}
        lpa, lpq, lpm = dists(model, b)
        worst = 0.0
        for step in range(min(3, len(b['adv']))):
            indexes = (b['li'] == step).nonzero().flatten()
            upos = list(zip(b['x'][indexes].tolist(), b['y'][indexes].tolist()))
            ua, uq, mk = bcm.forward(W, b['grid'][step].cpu().numpy(), b['glob'][step].cpu().numpy(),
                                     b['uv'][indexes].cpu().numpy(), upos)
            def logp(a):
                a = a - a.max(); return a - np.log(np.exp(a).sum())
            for j, u in enumerate(indexes.tolist()):
                mask = b['mask'][u].cpu().numpy()
                expected = logp(np.where(mask, ua[j] / TAU, -1e9))
                worst = max(worst, float(np.abs(expected[mask] - lpa[u].detach().cpu().numpy()[mask]).max()))
                qbound = max(1, int(b['qb'][u]))
                expectedq = logp(uq[j][:qbound] / TAU)
                worst = max(worst, float(np.abs(expectedq - lpq[u, :qbound].detach().cpu().numpy()).max()))
            for h, name in enumerate(MARKET_HEADS):
                worst = max(worst, float(np.abs(logp(mk[name] / TAU) - lpm[h][step].detach().cpu().numpy()).max()))
        assert worst < 0.002, ('export probability mismatch', worst)
        print('PARITY', worst, flush=True)

    def evaluate(label, path, seeds, select=False):
        nonlocal best_score, best_label
        jobs = [(seed, p, S_LIST, 0, TAU, path) for seed in seeds for p in (0, 1)]
        rows = summarize_eval(list(ex.map(rollout_group, jobs)))
        wins = sum(r['policy_margin'] > 0 for r in rows)
        draws = sum(r['policy_margin'] == 0 for r in rows)
        score = (wins + .5 * draws, float(np.mean([r['delta'] for r in rows])))
        out = dict(label=label, n=len(rows), wins=wins, draws=draws, mean_delta=score[1],
                   rows=rows, elapsed=round(time.time() - t_start), weights_sha256=hashlib.sha256(open(path, 'rb').read()).hexdigest())
        evaluations.append(out)
        json.dump(evaluations, open('/kaggle/working/evaluations.json', 'w'), indent=2)
        print('EVAL', json.dumps({k:v for k,v in out.items() if k != 'rows'}), flush=True)
        if select:
            selection_labels.append(label)
            if best_score is None or score > best_score:
                best_score, best_label = score, label
                shutil.copyfile(path, '/kaggle/working/best_model.npz')
        return out

    export('/kaggle/working/initial_model.npz')
    evaluate('initial_bc', '/kaggle/working/initial_model.npz', VAL_SEEDS, select=True)
    warm_rows = []
    for rows in ex.map(teacher_game, WARM_SEEDS):
        warm_rows.extend(rows)
    print('WARM_DATA', len(warm_rows), 'steps', len(WARM_SEEDS), 'seeds', flush=True)
    assert_export_parity(net, batch(warm_rows[:MB]))
    warm_opt = torch.optim.Adam(net.parameters(), lr=1e-4)
    for ep in range(WARM_EPOCHS):
        random.shuffle(warm_rows)
        losses = []
        for i in range(0, len(warm_rows), MB):
            b = batch(warm_rows[i:i+MB])
            la, lq, lm = taken(b, *dists(net, b))
            pick = (b['qb'] > 0).float()
            # Positive market events receive extra weight; validation decides whether this helps.
            market_weights = 1.0 + 2.0 * (b['mk'] > 0).float()
            loss = -la.mean() - (lq * pick).sum()/pick.sum().clamp(min=1) - 0.3*(lm*market_weights).sum(1).mean()
            warm_opt.zero_grad(); loss.backward()
            torch.nn.utils.clip_grad_norm_(net.parameters(), 1.0)
            warm_opt.step(); losses.append(float(loss))
        print('WARM', ep+1, float(np.mean(losses)), round(time.time()-t_start), flush=True)
    export('/kaggle/working/warm_model.npz')
    evaluate('warm_bc', '/kaggle/working/warm_model.npz', VAL_SEEDS, select=True)
    # Preserve the warmed policy as the reference for RL. Initial and warm checkpoints remain candidates.
    ref = copy.deepcopy(net).eval()
    for parameter in ref.parameters():
        parameter.requires_grad_(False)
    del warm_rows
    for it in range(ITERS):
        if time.time() - t_start > TIME_BUDGET:
            print('time budget reached', flush=True); break
        wpath = '/kaggle/working/w_%d.npz' % it
        export(wpath)
        rs = np.random.RandomState(830_000_000 + it)
        jobs = [(seed, p, S_LIST, K_SAMPLES, TAU, wpath) for seed in [int(rs.randint(830_000_000, 839_000_000)) for _ in range(GROUPS // 2)] for p in (0, 1)]
        t0 = time.time()
        groups = list(ex.map(rollout_group, jobs))
        t_roll = time.time() - t0
        steps = []; diag = {S: dict(g=[], s=[], best=[], v=[], gw=0, vw=0, n=0) for S in S_LIST}; errs = 0; lost = 0
        for g in groups:
            if g.get('error'):
                print('group error', g['error'], flush=True); continue
            lost += sum(1 for c in g['children'] if c['kind'] == 'lost')
            for S, e in group_stats(g).items():
                errs += e['errors']
                if e['v12'] is not None and e['greedy'] is not None and e['sample']:
                    d = diag[S]; d['n'] += 1
                    d['g'].append(e['greedy'] - e['v12']); d['s'].append(np.mean(e['sample']) - e['v12'])
                    d['best'].append(max(e['sample']) - e['v12']); d['v'].append(e['v12'])
                    d['gw'] += e['greedy'] > 0; d['vw'] += e['v12'] > 0
                if len(e['sample']) >= 2:
                    R = np.asarray(e['sample'], np.float64) / MARGIN_SCALE + WIN_W * np.sign(e['sample'])
                    adv = (R - R.mean()) / max(R.std(), SIGMA_MIN)
                    for a, rec in zip(adv, e['recs']):
                        for s in rec or []:
                            s['adv'] = float(a); steps.append(s)
        for S, d in diag.items():
            if d['n']:
                print('it %d S %d n %d | greedy-v12 %+.0f  sample-v12 %+.0f  best-v12 %+.0f | wins greedy %d v12 %d | v12 margin %+.0f' % (
                    it, S, d['n'], np.mean(d['g']), np.mean(d['s']), np.mean(d['best']), d['gw'], d['vw'], np.mean(d['v'])), flush=True)
        assert not errs and not lost, ('rollout errors', errs, lost)
        # PPO update
        stats = dict(pg=0.0, kl=0.0, n=0)
        if steps:
            random.shuffle(steps)
            with torch.no_grad():
                olds = []
                for i in range(0, len(steps), MB):
                    b = batch(steps[i:i + MB]); olds.append(taken(b, *dists(net, b)))
                    if it == 0 and i == 0:
                        assert_export_parity(net, b)
            for ep in range(PPO_EPOCHS):
                for bi, i in enumerate(range(0, len(steps), MB)):
                    b = batch(steps[i:i + MB]); oa, oq, om = olds[bi]
                    lpa, lpq, lpm = dists(net, b)
                    la, lq, lm = taken(b, lpa, lpq, lpm)
                    A_u = b['adv'][b['li']]; pick = (b['qb'] > 0).float()
                    def clip_obj(new, old, adv):
                        r = torch.exp(torch.clamp(new - old, -20, 20))
                        return torch.min(r * adv, torch.clamp(r, 1 - CLIP, 1 + CLIP) * adv)
                    new_joint = joint(b, la, lq, lm)
                    old_joint = joint(b, oa, oq, om)
                    obj = clip_obj(new_joint, old_joint, b['adv']).sum()
                    with torch.no_grad():
                        ra, rq, rm = dists(ref, b)
                    k = kl(lpa, ra).sum() + (kl(lpq, rq) * pick).sum() + sum(kl(lpm[j], rm[j]).sum() for j in range(len(MARKET_HEADS)))
                    n = len(b['adv'])
                    loss = (-obj + KL_BETA * k) / n
                    opt.zero_grad(); loss.backward()
                    torch.nn.utils.clip_grad_norm_(net.parameters(), 1.0); opt.step()
                    stats['pg'] += float(obj) / n; stats['kl'] += float(k) / n; stats['n'] += 1
        rec = dict(it=it, groups=len(groups), steps=len(steps), roll_s=round(t_roll), errors=errs, lost=lost,
                   pg=round(stats['pg'] / max(1, stats['n']), 4), kl=round(stats['kl'] / max(1, stats['n']), 4),
                   diag={S: dict(n=d['n'], greedy=round(float(np.mean(d['g'])), 1) if d['n'] else None,
                                 sample=round(float(np.mean(d['s'])), 1) if d['n'] else None) for S, d in diag.items()},
                   elapsed=round(time.time() - t_start))
        history.append(rec)
        print('ITER', json.dumps(rec), flush=True)
        export('/kaggle/working/rl_model.npz')
        if (it + 1) % EVAL_EVERY == 0 or it + 1 == ITERS:
            evaluate('rl_%03d' % (it + 1), '/kaggle/working/rl_model.npz', VAL_SEEDS, select=True)
        if time.time() - t_start > TIME_BUDGET:
            break
        json.dump(history, open('/kaggle/working/rl_history.json', 'w'))
        if os.path.exists(wpath):
            os.remove(wpath)
    export('/kaggle/working/last_model.npz')
    evaluate('last_update', '/kaggle/working/last_model.npz', VAL_SEEDS, select=True)
    # The test seeds have not appeared in training, warm-up, or checkpoint selection.
    initial_test = evaluate('test_initial', '/kaggle/working/initial_model.npz', TEST_SEEDS)
    best_test = evaluate('test_selected', '/kaggle/working/best_model.npz', TEST_SEEDS)
    summary = dict(selected_checkpoint=best_label, selection_score=best_score,
                   initial_test={k:v for k,v in initial_test.items() if k != 'rows'},
                   selected_test={k:v for k,v in best_test.items() if k != 'rows'},
                   iterations=len(history), training_transition_count=sum(r['steps'] for r in history),
                   elapsed=round(time.time()-t_start), incumbent='omw_v13f',
                   note='Experimental continuation policy. No competition submission. Codec retains documented limitations.')
    json.dump(summary, open('/kaggle/working/summary.json', 'w'), indent=2)
    print('FINAL', json.dumps(summary), flush=True)

    ex.shutdown(wait=True, cancel_futures=True)
    print('done', round(time.time() - t_start), 's', flush=True)


if __name__ == '__main__':
    main()
